<?php declare(strict_types=1);require_once __DIR__.'/database.php';function back(string $m):never{header('Location: index.php?msg='.urlencode($m));exit;}$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$n=trim($_POST['nombre']??'');$i=trim($_POST['identificacion']??'');$t=trim($_POST['telefono']??'');if(!$id||$n===''||$i===''||$t==='')back('Datos inválidos.');$pdo=getPDO();$q=$pdo->prepare('SELECT imagen FROM alumnos WHERE id=?');$q->execute([$id]);$a=$q->fetch();if(!$a)back('Alumno no encontrado.');$img=$a['imagen'];$newFile=null;if(isset($_FILES['imagen'])&&$_FILES['imagen']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['imagen'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>5242880)back('La nueva fotografía no es válida.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ok=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($ok[$mime])||@getimagesize($f['tmp_name'])===false)back('La nueva fotografía no es válida.');$img='alumno_'.bin2hex(random_bytes(16)).'.'.$ok[$mime];$dir=__DIR__ . '/';if(!move_uploaded_file($f['tmp_name'],$dir.$img))back('No se pudo guardar la fotografía.');$newFile=$dir.$img;}try{$q=$pdo->prepare('UPDATE alumnos SET nombre=?,identificacion=?,telefono=?,imagen=? WHERE id=?');$q->execute([$n,$i,$t,$img,$id]);if($newFile){$old=realpath(__DIR__ . '/'.basename($a['imagen']));$base=realpath(__DIR__ . '/');if($old&&$base&&str_starts_with($old,$base.DIRECTORY_SEPARATOR)&&is_file($old))@unlink($old);}back('Alumno actualizado correctamente.');}catch(Throwable $e){if($newFile)@unlink($newFile);back('No fue posible actualizar el alumno.');}
